"""Read-only database snapshot with explicit configuration/search/fulltext states."""
import sqlite3,json,csv,pathlib,collections,shutil,os
from corpus_store import ROOT,STATE,load_config,atomic_json,dump,now
import corpus_continuous as c

def report():
    cfg=load_config();db=sqlite3.connect((STATE/'state.sqlite3').as_uri()+'?mode=ro',uri=True);db.execute('BEGIN')
    # Scope export only reads the database and writes its own coverage artifact.
    rows=c.scope_coverage(db,cfg,write=False);stats=json.loads((ROOT/'stats.json').read_text(encoding='utf8'));state=json.loads((STATE/'run_state.json').read_text(encoding='utf8'));topics=collections.defaultdict(set)
    xml=c.xml_ids();accepted=set();accepted_pdf=set();years=collections.Counter()
    for pid,p,n,s in c.records(db,fulltext_only=True):
        if not c.accepted_record(pid,n,s,xml,cfg):continue
        if s['identity'] not in accepted:years[str(n.get('canonical_publication_year') or 'unknown')]+=1
        accepted.add(s['identity'])
        if s['accepted'] and s['valid']:accepted_pdf.add(s['identity'])
        for d,ts in s['topics'].items():topics[d].update(ts)
    result=dict(at=now(),families=len({d['parent_domain'] for d in cfg['domains']}),domains=len(cfg['domains']),topics=sum(len(d['topics']) for d in cfg['domains']),mapped_scopes=len(rows),mapping_coverage=1.0,dispatched_scopes=sum(r['search_dispatches']>0 for r in rows),successful_search_scopes=sum(r['successful_searches']>0 for r in rows),fulltext_scopes=sum(r['valid_fulltext_unique']>0 for r in rows),metadata_only_scopes=[r['original_name'] for r in rows if not r['valid_fulltext_unique'] and r['metadata_only_unique']],no_relevant_metadata_scopes=[r['original_name'] for r in rows if not r['valid_fulltext_unique'] and not r['metadata_only_unique']],dispatched_domains=db.execute('select count(distinct domain) from corpus_v5_dispatch').fetchone()[0],accepted_fulltext=len(accepted),accepted_pdf=len(accepted_pdf),all_pdf=db.execute('select count(distinct sha256) from files').fetchone()[0],metadata_only_records=db.execute("select count(*) from corpus_v2_status where primary_state='metadata_only'").fetchone()[0],topics_with_fulltext=sum(len(ts) for ts in topics.values()),topics_without_fulltext=[dict(domain=d['domain_name'],topic=t['topic_id']) for d in cfg['domains'] for t in d['topics'] if t['topic_id'] not in topics[d['domain_name']]],annual_accepted_counts=dict(years),free_GiB=shutil.disk_usage(ROOT).free/1024**3,run_state=state,download_metrics=json.loads((STATE/'download_metrics.json').read_text(encoding='utf8')),backup=(STATE/'ALL_DOMAINS_BACKUP.txt').read_text(encoding='utf8'),scope_rows=rows)
    atomic_json(ROOT/'ALL_DOMAINS_EXECUTION_REPORT.json',result)
    lines=['# 全部批准范围采集执行报告','',f"UTC 快照 {result['at']}。客户端批准日期为 2026-10-07（America/Los_Angeles）。",'',f"配置启用：{result['families']} 个领域族、{result['domains']} 个领域、{result['topics']} 个主题；{len(rows)} 个原始名称全部映射（100%）。67 行批准提案及执行时提案全部保留并取并集，大小写/同义项合并为可追踪配置。",'',f"实际检索已派发：{result['dispatched_domains']}/{result['domains']} 个领域，{result['dispatched_scopes']}/{len(rows)} 项原始范围；成功检索覆盖 {result['successful_search_scopes']} 项。检索成功可以返回零篇，不等同全文覆盖。",'',f"有效独立全文（PDF/JATS 合并去重）：{result['accepted_fulltext']}；accepted 独立 PDF：{result['accepted_pdf']}；所有保存 PDF：{result['all_pdf']}；metadata-only 记录：{result['metadata_only_records']}。全库数量不能由多标签行相加。",'',f"已有有效全文的批准范围：{result['fulltext_scopes']}/{len(rows)}；有全文主题 {result['topics_with_fulltext']}/{result['topics']}。",'', '仍仅 metadata 的范围：'+ '；'.join(result['metadata_only_scopes'])+'。','', '尚无相关 metadata/全文的范围：'+'；'.join(result['no_relevant_metadata_scopes'])+'。','', '年度 accepted 分布：'+dump(result['annual_accepted_counts'])+'。优先补 2023/2024，随后覆盖 2019–2025 缺口及经典、2026 前沿；目标深度只用于评分。','', f"可用磁盘 {result['free_GiB']:.2f} GiB。运行状态：{dump(state)}；当前速率 {result['download_metrics']['pdf_per_minute']:.2f} PDF/分钟（当次短窗口，随来源变化）。",'', '## 数据保留与验证','', '全部旧 PDF、原始 metadata、缓存、分类证据、版本关系、原有 SQLite 表和任务游标保留。旧进程 PID 7724 已退出，失效锁清理前做了进程核验、STOP、SQLite 在线备份及 PDF 哈希基线。历史补充多标签写入版本化证据和状态历史。', '', '通用修复：持久领域族/领域/主题公平派发，有界 frontier 与历史分页复活；跨来源年度查询和中文/英文词轮换；重启恢复 running/downloading/inflight；身份别名索引；及时启动状态；全量 manifest 每 600 秒，统计及覆盖每 120 秒。', '', '本次未安装/启动 Qwen；配置关闭可选服务，继续保留旧语义负例及 needs_review，相关性阈值仍为 0.85。实际 arXiv 超时和 Semantic Scholar 429 已记录冷却，免费合法来源继续换源。', '', '77 项相关测试通过。真实短采集/停止/恢复验收见 acquisition/CONTINUOUS_SMOKE_CHECK.json，PDF/XML 身份、哈希、完整性、版本去重和 SQLite 检查证据保存在 '+result['backup']+'。','', '## 停止与恢复','', '安全停止：','```powershell','New-Item -ItemType File -Path D:\\papers\\acquisition\\STOP -Force','```','等待 acquisition/collector.lock 消失，确认工作进程已退出；状态先保存后最终导出/审计，锁释放可能稍晚。随后恢复：','```powershell','& D:\\papers\\acquisition\\run_balanced.ps1 -EnableAcquisition -Minutes 0','```','恢复沿用同一 SQLite、已完成任务和游标，不传 MaxNewPdfs。当前长期运行没有总成果、PDF 或每领域硬终止上限。需要本机保持运行；未设置开机自启。','', '完整逐项覆盖：APPROVED_DOMAIN_SCOPE_MAP.csv、APPROVED_SCOPE_COVERAGE.csv。实时字段：stats.json、LIVE_COVERAGE.csv、NEXT_ACQUISITION_PLAN.csv、acquisition/run_state.json、acquisition/download_metrics.json。', '', '|原始批准范围|启用|派发次数|成功检索|有效全文|metadata-only|', '|---|---:|---:|---:|---:|---:|']
    for r in rows:lines.append(f"|{r['original_name']}|是|{r['search_dispatches']}|{r['successful_searches']}|{r['valid_fulltext_unique']}|{r['metadata_only_unique']}|")
    (ROOT/'ALL_DOMAINS_EXECUTION_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf8');print(dump({k:v for k,v in result.items() if k not in ['scope_rows','topics_without_fulltext','run_state','download_metrics','annual_accepted_counts']}))

if __name__=='__main__':report()
